{
  "name": "数字输入输出端口模块",
  "name_en": "Digital Input/Output Port Module",
  "manufacturer": "Yoctopuce",
  "description": "用于控制和读取多路数字输入/输出通道的硬件模块。可按端口或按位设置通道状态、输入/输出方向、极性、开漏模式和输出电压，并支持定时脉冲与延时脉冲，适合实验中的开关量采集、触发输出和外部设备联动控制。",
  "description_en": "A hardware digital input/output module used to read and control multiple digital channels. It supports port-wide or per-bit control of state, input/output direction, polarity, open-drain mode, and output voltage, and can generate timed or delayed pulses for lab trigger I/O, switch-state acquisition, and external device interfacing.",
  "tag_hints": [
    "digital I/O",
    "trigger pulse generation",
    "open-drain outputs",
    "port direction control",
    "switch state sensing",
    "external device interfacing",
    "Yoctopuce"
  ],
  "actions": [
    {
      "action_name": "auto-set_portState",
      "description": "设置整个数字 I/O 端口各通道的状态位图。",
      "description_en": "Set the state bitmap of all channels on the digital I/O port."
    },
    {
      "action_name": "auto-set_portDirection",
      "description": "设置整个数字 I/O 端口各通道的输入/输出方向位图。",
      "description_en": "Set the input/output direction bitmap of all channels on the digital I/O port."
    },
    {
      "action_name": "auto-set_portOpenDrain",
      "description": "设置整个数字 I/O 端口各通道的开漏模式位图。",
      "description_en": "Set the open-drain mode bitmap of all channels on the digital I/O port."
    },
    {
      "action_name": "auto-set_portPolarity",
      "description": "设置整个数字 I/O 端口各通道的极性位图。",
      "description_en": "Set the polarity bitmap of all channels on the digital I/O port."
    },
    {
      "action_name": "auto-set_outputVoltage",
      "description": "设置输出通道的驱动电压源。",
      "description_en": "Set the drive voltage source for output channels."
    },
    {
      "action_name": "auto-set_command",
      "description": "设置设备命令字符串。",
      "description_en": "Set the device command string."
    },
    {
      "action_name": "auto-set_bitState",
      "description": "设置单个通道的状态。",
      "description_en": "Set the state of a single channel."
    },
    {
      "action_name": "auto-toggle_bitState",
      "description": "切换单个通道的状态。",
      "description_en": "Toggle the state of a single channel."
    },
    {
      "action_name": "auto-set_bitDirection",
      "description": "设置单个通道的输入/输出方向。",
      "description_en": "Set the input/output direction of a single channel."
    },
    {
      "action_name": "auto-set_bitPolarity",
      "description": "设置单个通道的极性。",
      "description_en": "Set the polarity of a single channel."
    },
    {
      "action_name": "auto-set_bitOpenDrain",
      "description": "设置单个通道的开漏模式。",
      "description_en": "Set the open-drain mode of a single channel."
    },
    {
      "action_name": "auto-pulse",
      "description": "在单个通道上输出指定时长的脉冲。",
      "description_en": "Generate a pulse of specified duration on a single channel."
    },
    {
      "action_name": "auto-delayedPulse",
      "description": "在单个通道上安排延时脉冲输出。",
      "description_en": "Schedule a delayed pulse on a single channel."
    },
    {
      "action_name": "auto-nextDigitalIO",
      "description": "枚举下一个可访问的数字 I/O 端口。",
      "description_en": "Enumerate the next accessible digital I/O port."
    }
  ]
}

